window.kbPageData["views/entry/k-442e48c9c67c3602"] = {"key":"entry/k-442e48c9c67c3602","state":{"route":"entry/k-442e48c9c67c3602"},"node":{"id":"k-442e48c9c67c3602","mode":"k","title":"古典概型","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["古典概型中事件概率等于有利结果数除以等可能结果总数","等可能事件的概率等于有利结果数除以总结果数","等可能情形下的概率等于符合条件的结果数除以总结果数","等可能情形下事件概率等于有利结果数除以全部结果数","古典概型的概率计算公式","古典概型的概率计算","等可能基本结果下的事件概率等于有利结果数除以全部结果数","古典概型的概率公式","古典概型中事件概率等于有利结果数除以总结果数"],"qs":["国考 2023 副省级 行测#65","国考 2023 副省级 行测#71","国考 2023 行政执法 行测#64","国考 2023 行政执法 行测#66","国考 2024 地市级 行测#67","国考 2024 行政执法 行测#64","国考 2025 副省级 行测#79","国考 2025 地市级 行测#74","江苏 2023 B类 行测#63","江苏 2024 A类 行测#59"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":1,"reviewSet":"多题条目","independentCount":9,"directorySummary":"古典概型是基本结果有限且各基本结果等可能的概率模型。某事件的概率等于该事件包含的基本结果数除以全部基本结果数。","review":{"title":"古典概型","type":"原理与机制","definition":"古典概型是基本结果有限且各基本结果等可能的概率模型。某事件的概率等于该事件包含的基本结果数除以全部基本结果数。","explanation":"计算时，分子和分母取自同一个等可能样本空间。逐次独立抽取时，如果每次抽取的各个结果等可能，可以把按先后次序组成的结果作为基本结果。从全部合法方案中等可能地选取一个方案时，每个合法方案就是一个基本结果。","basis":"据关联原题和解析编释。","references":[],"related":["k-a46327dbbd24e070"],"examFocus":{"国考 2023 副省级 行测#65":"按可重复抽取的条件，结合单周抽中甲办公室职工的概率，判断连续两周均抽中甲办公室职工的概率区间。","国考 2023 副省级 行测#71":"用古典概型比较满足甲、乙、丙位置限制的排法中，丁、戊相邻的排法与全部排法。","国考 2023 行政执法 行测#66":"用插板法统计每家至少分到一个名额的方案，再考虑恰有三家名额相同的方案占比。","国考 2024 地市级 行测#67":"把三人各自的完整三周行程合在一起作为一个基本结果，比较每周去处都互不相同的安排与全部安排。","国考 2024 行政执法 行测#64":"把三人各自的完整三周行程合在一起作为一个基本结果，比较每周去处都互不相同的安排与全部安排。","国考 2025 副省级 行测#79":"把每门课连续两天视为一个整体，用插空法考虑三个休息日两两不相邻的安排占比。","国考 2025 地市级 行测#74":"把每门课连续两天视为一个整体，用插空法考虑三个休息日两两不相邻的安排占比。","江苏 2023 B类 行测#63":"按三人各自选定的到岗天数，用组合计数比较三人的安排都包含周三的情形与全部安排。","江苏 2024 A类 行测#59":"把入选节目视为无序组合，用对立事件处理指定科室至少有一个节目入选的概率。"}},"readings":[{"origin":"k-442e48c9c67c3602","title":"古典概型","qs":["国考 2023 副省级 行测#65","国考 2023 行政执法 行测#64","国考 2023 行政执法 行测#66","国考 2025 地市级 行测#74"],"definition":"古典概型是基本结果有限且各基本结果等可能的概率模型。某事件的概率等于该事件包含的基本结果数除以全部基本结果数。","explanation":"计算时，分子和分母取自同一个等可能样本空间。逐次独立抽取时，如果每次抽取的各个结果等可能，可以把按先后次序组成的结果作为基本结果。从全部合法方案中等可能地选取一个方案时，每个合法方案就是一个基本结果。","evidence":"","doubt":"","references":[]},{"origin":"k-19ab1e80d8f787bb","title":"古典概型","qs":["江苏 2024 A类 行测#59"],"definition":"古典概型的基本结果个数有限且各结果等可能。任一事件的概率等于该事件包含的基本结果数除以全部基本结果数。","explanation":"第 59 题从 8 个节目中随机选出 3 个，入选顺序不影响结果，因此每个无序的三节目组合都是一个等可能的基本结果，共有 C(8,3)=56 种。从其余 6 个节目中选 3 个的 C(6,3)=20 种组合都使小张所在科室的节目全部落选。其余 36 种组合满足题意，所求概率为 36/56=9/14，对应 D 项。","evidence":"总情况是从8个节目中随机选出3个","doubt":"","references":[]},{"origin":"k-1d42b53012368790","title":"古典概型","qs":["江苏 2023 B类 行测#63"],"definition":"当试验的基本结果只有有限个且各结果等可能时，某事件的概率等于该事件包含的基本结果数除以全部基本结果数。","explanation":"本题按三人各自等可能、相互独立地选日计算，把三人的一组选日安排视为一个基本结果。小王、小李和小陈分别从5天中选2、3、4天，全部安排有10×10×5＝500种。三人都选周三时，各自还需从其余4天中选1、2、3天，符合条件的安排有4×6×4＝96种。因此所求概率为96/500＝24/125，对应C项。","evidence":"分别从下周的周一到周五中随机选2天、3天、4天去公司工作","doubt":"","references":[]},{"origin":"k-7bf5b52e5f85127d","title":"古典概型","qs":["国考 2025 副省级 行测#79"],"definition":"当基本结果数有限且各结果等可能时，事件的概率等于满足该事件条件的基本结果数除以全部基本结果数。","explanation":"本题在所有安排中等可能地选取一种。将甲、乙课程各自连续的两天视为一个整体，与三个休息日一起排列。从五个位置中选两个放课程，再确定甲、乙的顺序，共有 C(5,2)×2＝20 种安排。三个休息日要两两不相邻，只能在两门课程之前、之间和之后各放一天。甲、乙顺序有两种，因此符合条件的安排有两种，所求概率为 2/20＝1/10，对应 D。","evidence":"如在所有可能的安排中随机选择1种","doubt":"","references":[]},{"origin":"k-de42e096c9194721","title":"古典概型","qs":["国考 2023 副省级 行测#71"],"definition":"古典概型的样本空间包含有限个等可能的基本结果。某事件的概率等于该事件包含的基本结果数除以样本空间的基本结果总数。","explanation":"第71题从符合甲、乙、丙位置限制的讲解次序中等可能地选取一种。丙有2个位置可选，甲、乙在第二至第五位的其余3个位置中有3×2种排法，丁、戊、己有6种排法，共72种。丙在第三位时，甲、乙占第二和第四位或第四和第五位才会留下可供丁、戊相邻的空位。每种占位下甲、乙和丁、戊各可互换，合计8种。丙在第四位时，将次序倒排可得同样的8种。因此所求概率为16/72＝2/9，对应A项。","evidence":"在满足以上条件的次序中随机选择一个","doubt":"","references":[]},{"origin":"k-e365e01c0d0ca4ac","title":"古典概型的概率计算","qs":["国考 2024 地市级 行测#67"],"definition":"当基本结果的个数有限且每个基本结果等可能时，某事件的概率等于包含在该事件中的基本结果数除以全部基本结果数。","explanation":"第 67 题按三人各自独立、等可能地选择调研顺序理解，216 套完整安排等可能。第一周三人分去三个不同地点，有 6 种排法。以第一周甲、乙、丙分别去 A、B、C 为例，第二周三人各自必须换地点且仍要分去三个不同地点，按甲、乙、丙的顺序只有 B、C、A 和 C、A、B 两种。第三周每人去前两周未去的地点，安排随之确定，且三人去处仍各不相同。因此有利结果共 6×2＝12 套，概率为 12÷216＝1/18，对应 C 项。","evidence":"满足要求的情况数为6×2=12种情况","doubt":"","references":[]},{"origin":"k-f30178a6daf5f176","title":"古典概型的概率公式","qs":["国考 2024 行政执法 行测#64"],"definition":"当所有基本结果有限且等可能时，某事件的概率等于该事件包含的基本结果数除以全部基本结果数。","explanation":"第64题按三人各自独立、等可能地选择调研顺序理解。把三个人各自完整的三周顺序合在一起作为一个基本结果，共有216种等可能的安排。其中12种满足三周里每一周三人去处都不同，所求概率为12÷216＝1/18，对应选项C。","evidence":"如每个人随机安排顺序","doubt":"","references":[]}],"aspects":[{"title":"可重复抽取的有序结果","uses":[{"unit":"Q1","role":"解题依据","use":"两周都从同一批9名职工中独立随机抽取1人，允许重复选中。按周次计有9²种结果，其中两周均抽到甲办公室职工的有5²种，概率为25/81，约30.86%，选B。","evidence":"每周从这9名职工中随机抽取1人下沉社区担任志愿者（同一人有可能被连续、重复选中）。","qids":["国考 2023 副省级 行测#65","国考 2023 行政执法 行测#64"]}]},{"title":"正整数分配方案","uses":[{"unit":"Q2","role":"解题依据","use":"将10个相同名额分给4个不同分公司且每家至少得1个，用插板法得到84种方案。三家各得的名额可以是1、2或3个，每种情况都有4种方式确定名额不同的那家，共12种，概率为1/7，选D。","evidence":"要求在每个分公司至少分配1个名额的所有分配方案中，随机选择1个方案实施","qids":["国考 2023 行政执法 行测#66"]}]},{"title":"连续课程与间隔日","uses":[{"unit":"Q3","role":"解题依据","use":"将甲、乙各自连续的2天分别视为一个整体，与3个空闲日一起排列，共20种安排。要使3个空闲日互不相邻，两个课程整体的前、中、后三处各须安排1个空闲日，只剩甲、乙的两种先后顺序，概率为2/20，即1/10，选D。","evidence":"如在所有可能的安排中随机选择1种，不用学习的3天均不相邻的概率为：","qids":["国考 2025 地市级 行测#74"]}]}]},"questions":{"国考 2023 副省级 行测#65":{"paper":"国考 2023 副省级 行测","n":65,"mod":"数量关系","src":["503793642e845de9795f.pdf",12],"asrc":["ecade1ff5af69283232e.pdf",20],"card":"2e0de00cfb22e7971a29df45","links":[{"id":"k-442e48c9c67c3602","role":"解题依据","why":"把两周抽取视为等可能的有序结果，用有利结果数与总结果数的比值求概率。"}]},"国考 2023 副省级 行测#71":{"paper":"国考 2023 副省级 行测","n":71,"mod":"数量关系","src":["503793642e845de9795f.pdf",13],"asrc":["ecade1ff5af69283232e.pdf",21],"card":"b609151a69bc0724c0b91316","links":[{"id":"k-442e48c9c67c3602","role":"解题依据","why":"在等可能的有限样本空间中，事件概率等于符合事件的结果数除以样本空间的结果总数。"}]},"国考 2023 行政执法 行测#64":{"paper":"国考 2023 行政执法 行测","n":64,"mod":"数量关系","src":["857378cf496f27296500.pdf",11],"asrc":["d23139fe5a0fb3115135.pdf",20],"card":"e8e48bcdd1bf70b5935a4dfb","links":[{"id":"k-442e48c9c67c3602","role":"解题依据","why":"以两周抽取形成的有序结果为样本，按全体结果数与两周均来自甲办公室的结果数计算概率。"}]},"国考 2023 行政执法 行测#66":{"paper":"国考 2023 行政执法 行测","n":66,"mod":"数量关系","src":["857378cf496f27296500.pdf",11],"asrc":["d23139fe5a0fb3115135.pdf",20],"card":"e8e48bcdd1bf70b5935a4dfb","links":[{"id":"k-442e48c9c67c3602","role":"解题依据","why":"以等可能的分配方案为样本，用符合名额相同条件的方案数与总方案数之比求概率。"}]},"国考 2024 地市级 行测#67":{"paper":"国考 2024 地市级 行测","n":67,"mod":"数量关系","src":["92d0b72e86a6a33d568d.pdf",12],"asrc":["e1792c53900a45f1b9fa.pdf",20],"card":"6f20278fb310ec4c8aa778a3","links":[{"id":"k-442e48c9c67c3602","role":"直接考查","why":"各套调研顺序可作为等可能结果，按符合条件的安排数占总安排数的比例计算概率。"}]},"国考 2024 行政执法 行测#64":{"paper":"国考 2024 行政执法 行测","n":64,"mod":"数量关系","src":["dfddc59dc6e7d9da5d71.pdf",11],"asrc":["6493f3a6a55c38431852.pdf",19],"card":"e734819e5c214a3dce6257c6","links":[{"id":"k-442e48c9c67c3602","role":"解题依据","why":"将随机顺序视为等可能安排后，可以用符合逐周限制的安排数与总安排数求比值。"}]},"国考 2025 副省级 行测#79":{"paper":"国考 2025 副省级 行测","n":79,"mod":"数量关系","src":["ffe12c35a46d4df574ec.pdf",13],"asrc":["ff0b352b44d417525086.pdf",24],"card":"4cb7ccaec7cc18717d3226f7","links":[{"id":"k-442e48c9c67c3602","role":"解题依据","why":"随机选择安排时，用符合休息日要求的安排数占全部安排数的比例求概率。"}]},"国考 2025 地市级 行测#74":{"paper":"国考 2025 地市级 行测","n":74,"mod":"数量关系","src":["31f401e91aef8d11365d.pdf",13],"asrc":["8cece062c7c079b53130.pdf",23],"card":"63d35350d33b8f087aa1e199","links":[{"id":"k-442e48c9c67c3602","role":"解题依据","why":"各合法安排等可能，可用符合休息日限制的安排数除以合法安排总数。"}]},"江苏 2023 B类 行测#63":{"paper":"江苏 2023 B类 行测","n":63,"mod":"数量关系","src":["22262c34d18cd68fbee4.pdf",11],"asrc":["b08f2713d73015eac675.pdf",19],"card":"1193f019bef5c21aeb3b0246","links":[{"id":"k-442e48c9c67c3602","role":"解题依据","why":"把三人的选日结果组成联合样本，用三份安排均含周三的组合数与全部组合数之比求概率。"}]},"江苏 2024 A类 行测#59":{"paper":"江苏 2024 A类 行测","n":59,"mod":"数量关系","src":["f8fec75f67d6d1ba5759.pdf",10],"asrc":["0126a1c8aceee632ea2b.pdf",17],"card":"5b1dc0b3f466e8cd25123e80","links":[{"id":"k-442e48c9c67c3602","role":"解题依据","why":"每种三节目组合等可能，可用相应组合数与总组合数之比求出概率。"}]}},"terms":{"k-a46327dbbd24e070":{"id":"k-a46327dbbd24e070","mode":"k","type":"原理与机制","title":"等可能组合与事件概率","qs":[],"count":2}},"references":{},"topics":[],"units":{"k-442e48c9c67c3602":[["国考 2023 副省级 行测#65","国考 2023 行政执法 行测#64"],["国考 2023 副省级 行测#71"],["国考 2023 行政执法 行测#66"],["国考 2024 地市级 行测#67"],["国考 2024 行政执法 行测#64"],["国考 2025 副省级 行测#79"],["国考 2025 地市级 行测#74"],["江苏 2023 B类 行测#63"],["江苏 2024 A类 行测#59"]]}};
